using System.Collections.Generic;
using UnityEngine;

namespace TLDRevamp.Net
{
    /// Log only: a building one player has and another standing near it hasn't (playtests 2026-10-10 and 2026-10-16:
    /// "some buildings show up for me but not for the other player", same seed). Buildings are generated by each machine on its
    /// own (poiGenScript: seeded by map seed and chunk; placed along roads once the roads there are done), so nothing in
    /// the session sees the difference — the lease check (Entities.Leases) only compares the type where both machines
    /// generated a building at the same spot. Here every machine reports the buildings around its player every few
    /// seconds (key, type, shown or only generated, its draw-distance setting); the server compares players standing
    /// near each other and writes "[anomaly] building …" naming the building, the spot and what the other player has
    /// there instead (nothing, the same building a few metres off, another type, generated but not shown).
    public static partial class Entities
    {
        public const byte PoiCensus = 84;   // c→s: f64 gx, f64 gz, f32 drawLerp, u8 distant terrain, f32 shown within, f32 removed beyond, u16 n × (f64 x, f64 z, i32 type, u8 shown)
        public static bool PoiCensusOn = true;
        public static float PoiCensusEveryS = 5f, PoiCensusRadiusM = 250f, PoiCensusNearM = 120f;
        public static long PoiCensusSent, PoiCensusIn, PoiDiffers;
        private static float _poiCensusAt;

        private struct PoiSeen { public double X, Z; public int Type; public bool Shown; public string Name; }
        private sealed class PoiReport { public double X, Z; public float DrawLerp, ShowM, RemoveM; public bool Distant; public float At; public readonly List<PoiSeen> Pois = new List<PoiSeen>(); }
        private static readonly Dictionary<int, PoiReport> _poiLists = new Dictionary<int, PoiReport>();
        private static readonly HashSet<string> _poiLogged = new HashSet<string>();

        private static void PoiCensusTick()
        {
            if (!PoiCensusOn || Time.realtimeSinceStartup - _poiCensusAt < PoiCensusEveryS) return;
            _poiCensusAt = Time.realtimeSinceStartup;
            var map = menuhandler.s != null ? menuhandler.s.currentMainMap : null;
            var pl = mainscript.s != null ? mainscript.s.player : null;
            if (map == null || map.poiGens == null || pl == null || settingsscript.s == null || settingsscript.s.S == null) return;
            var me = mainscript.GlobalFromUnityPos(pl.transform.position);
            W.Reset(); W.U8(PoiCensus); W.F64(me.x); W.F64(me.z);
            W.F32(settingsscript.s.S.GetDrawDistanceLerp()); W.Bool(settingsscript.s.S.GetDistantTerrain());
            var pg0 = map.poiGens.Count > 0 ? map.poiGens[0] : null;   // the distances the game shows buildings within (from the draw-distance setting)
            W.F32(pg0 != null ? pg0.lodDistance : -1f); W.F32(pg0 != null ? pg0.removeDistance : -1f);
            int countAt = W.Len; W.U16(0);
            int n = 0;
            double r2 = (double)PoiCensusRadiusM * PoiCensusRadiusM;
            foreach (var pg in map.poiGens)
            {
                if (pg == null || pg.chunks == null) continue;
                foreach (var ch in pg.chunks.Values)
                {
                    if (ch == null || ch.pois == null) continue;
                    foreach (var p in ch.pois.Values)
                    {
                        if (p == null) continue;
                        double dx = p.pos.x - me.x, dz = p.pos.z - me.z;
                        if (dx * dx + dz * dz > r2) continue;
                        W.F64(p.posID.x); W.F64(p.posID.z); W.I32(p.id);
                        W.Bool(p.pobj != null && p.pobj.gameObject.activeInHierarchy);
                        if (++n >= 200) break;
                    }
                }
            }
            W.Buf[countAt] = (byte)n; W.Buf[countAt + 1] = (byte)(n >> 8);
            ToServer(W, true);
            PoiCensusSent++;
        }

        /// Server: keep this player's list; compare it with every player's near enough to the same buildings.
        internal static void ServerPoiCensus(int from, NetReader r)
        {
            var l = new PoiReport { X = r.F64(), Z = r.F64(), DrawLerp = r.F32(), Distant = r.Bool(), ShowM = r.F32(), RemoveM = r.F32(), At = Time.realtimeSinceStartup };
            int n = r.U16();
            for (int i = 0; i < n && !r.Bad; i++)
                l.Pois.Add(new PoiSeen { X = r.F64(), Z = r.F64(), Type = r.I32(), Shown = r.Bool() });
            if (r.Bad || !Finite(new Vector3d(l.X, 0, l.Z))) return;
            for (int i = 0; i < l.Pois.Count; i++) { var p = l.Pois[i]; p.Name = BuildingName(p.Type); l.Pois[i] = p; }
            _poiLists[from] = l;
            PoiCensusIn++;
            foreach (var kv in _poiLists)
            {
                if (kv.Key == from || Time.realtimeSinceStartup - kv.Value.At > 3f * PoiCensusEveryS) continue;
                ComparePois(kv.Key, kv.Value, from, l);
                ComparePois(from, l, kv.Key, kv.Value);
            }
        }

        /// What `a` has close to both players that `b` hasn't (b's list covers PoiCensusRadiusM around b).
        private static void ComparePois(int aId, PoiReport a, int bId, PoiReport b)
        {
            double near2 = (double)PoiCensusNearM * PoiCensusNearM;
            foreach (var p in a.Pois)
            {
                if (!p.Shown) continue;
                double da = Sq(p.X - a.X, p.Z - a.Z), db = Sq(p.X - b.X, p.Z - b.Z);
                if (da > near2 || db > near2) continue;
                PoiSeen same = default, other = default; bool hasSame = false, hasOther = false; double ds = double.MaxValue, dother = double.MaxValue;
                foreach (var q in b.Pois)
                {
                    double d = Sq(q.X - p.X, q.Z - p.Z);
                    if (d < 0.01 && q.Type == p.Type) { same = q; hasSame = true; ds = 0; break; }
                    if (q.Type == p.Type && d < ds) { same = q; hasSame = true; ds = d; }
                    if (q.Type != p.Type && d < dother) { other = q; hasOther = true; dother = d; }
                }
                string why;
                if (hasSame && ds < 0.01) { if (same.Shown) continue; why = "generated there but not shown"; }
                else if (hasSame && ds < 300.0 * 300.0) why = $"the same building {System.Math.Sqrt(ds):F1} m off, at {same.X:F1},{same.Z:F1}";
                else if (hasOther && dother < 60.0 * 60.0) why = $"{other.Name} (type {other.Type}) {System.Math.Sqrt(dother):F0} m from it";
                else why = "no building there";
                string key = p.X.ToString("F1", System.Globalization.CultureInfo.InvariantCulture) + "," + p.Z.ToString("F1", System.Globalization.CultureInfo.InvariantCulture) + ">" + bId;
                if (!_poiLogged.Add(key)) continue;
                PoiDiffers++;
                Anomaly($"building differs between players: player {aId} has {p.Name} (type {p.Type}) at {p.X:F1},{p.Z:F1}; player {bId}, " +
                        $"{System.Math.Sqrt(db):F0} m from it, has {why} (draw distance {a.DrawLerp:F2} vs {b.DrawLerp:F2}: buildings shown within {a.ShowM:F0} / {b.ShowM:F0} m, removed beyond {a.RemoveM:F0} / {b.RemoveM:F0} m)");
            }
        }

        private static double Sq(double x, double z) => x * x + z * z;

        private static string BuildingName(int type)
        {
            try { var go = itemdatabase.s != null && type >= 0 ? itemdatabase.s.Building(type) : null; return go != null ? go.name : "building " + type; }
            catch { return "building " + type; }
        }

        internal static void ResetPoiCensus() { _poiLists.Clear(); _poiLogged.Clear(); _poiCensusAt = 0f; }
    }
}
